SELECT analytics_order_facts.channel, SUM(analytics_order_facts.contribution_margin) / CAST(NULLIF(SUM(analytics_order_facts.net_revenue), 0) AS DECIMAL) AS contribution_margin_pct FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 5 AND analytics_order_facts.region = 'South' AND analytics_order_facts.customer_segment = 'mid_market' AND analytics_order_facts.category = 'category_10' GROUP BY analytics_order_facts.channel ORDER BY contribution_margin_pct DESC, analytics_order_facts.channel ASC LIMIT 12
